1	import { encodeCanonical, hashDomain } from "@ts-drp/canonical";
2	import type {
3		DurableIssuanceOutboxRecord,
4		DurableIssuanceStore,
5		DurableIssueCommit,
6		DurableIssueScope,
7		SettlementPlan,
8	} from "@ts-drp/issuance-store";
9	import type {
10		DurableLiveJournalStore,
11		LiveJournalAcceptedRow,
12		LiveJournalScope,
13		LiveJournalSnapshotToken,
14	} from "@ts-drp/live-journal";
15	import type { DRPNetworkNode } from "@ts-drp/types";
16	import { vi } from "vitest";
17	
18	import { type PreparedV3Live, type RecoveredV3Live, recoverV3LiveReplica } from "../../../packages/node/src/v3-live.js";
19	import { type GenuinePreparedV3Fixture } from "../phase-3a1b-p3/live-fixture.js";
20	
21	export type OperationAdmissionReservationFixture =
22		| Readonly<{ readonly kind: "fresh"; commit(): "committed"; release(): void }>
23		| Readonly<{ readonly kind: "duplicate" | "conflict" | "rejected" }>;
24	
25	export interface OperationAdmissionPolicyFixture {
26		reserve(operation: Readonly<Record<string, unknown>>): OperationAdmissionReservationFixture;
27	}
28	
29	/**
30	 * Builds the same in-memory network used by the Phase 4a live-fold owner.
31	 * @param peerId - Distinct peer identity for this recovered replica.
32	 * @returns A network node with recorded topic membership.
33	 */
34	export function fakeNetwork(peerId: string): DRPNetworkNode {
35		const topics = new Set<string>();
36		return {
37			peerId,
38			membershipVerifier: undefined,
39			start: vi.fn(() => Promise.resolve()),
40			stop: vi.fn(() => Promise.resolve()),
41			restart: vi.fn(() => Promise.resolve()),
42			isDialable: vi.fn(() => Promise.resolve(true)),
43			changeTopicScoreParams: vi.fn(),
44			removeTopicScoreParams: vi.fn(),
45			subscribe: vi.fn((topic: string) => topics.add(topic)),
46			unsubscribe: vi.fn((topic: string) => topics.delete(topic)),
47			connectToBootstraps: vi.fn(() => Promise.resolve()),
48			connect: vi.fn(() => Promise.resolve()),
49			disconnect: vi.fn(() => Promise.resolve()),
50			getPeerMultiaddrs: vi.fn(() => Promise.resolve([])),
51			getBootstrapNodes: vi.fn(() => []),
52			getSubscribedTopics: vi.fn(() => [...topics]),
53			getMultiaddrs: vi.fn(() => ["/ip4/127.0.0.1/tcp/1"]),
54			getAllPeers: vi.fn(() => []),
55			getGroupPeers: vi.fn(() => []),
56			broadcastMessage: vi.fn(() => Promise.resolve()),
57			publishMessage: vi.fn(() => Promise.resolve(true)),
58			sendMessage: vi.fn(() => Promise.resolve()),
59			sendMessageToRandomPeer: vi.fn(() => Promise.resolve()),
60			sendGroupMessage: vi.fn(() => Promise.resolve()),
61			subscribeToMessageQueue: vi.fn(),
62			onGroupPeerChange: vi.fn((): (() => void) => () => undefined),
63			gossipTopicFor: vi.fn(() => undefined),
64		} as unknown as DRPNetworkNode;
65	}
66	
67	function journalStore(fixture: GenuinePreparedV3Fixture, trace?: string[]): DurableLiveJournalStore {
68		const scope: LiveJournalScope = Object.freeze({
69			anchorDigest: fixture.anchorDigest,
70			epoch: 0,
71			objectId: fixture.objectId,
72		});
73		const rows: LiveJournalAcceptedRow[] = [];
74		let genesisInstalled = false;
75		const snapshot = (): LiveJournalSnapshotToken =>
76			Object.freeze({
77				genesisDigest: "1".repeat(64),
78				highWatermark: Math.max(0, rows.length - 1),
79				kind: "v3-live-journal-snapshot-token-1" as const,
80				orderedRowDigest: "2".repeat(64),
81				parametersDigest: fixture.descriptor.parametersDigest,
82				scope,
83				snapshotDigest: "3".repeat(64),
84			});
85		return Object.freeze({
86			appendAccepted: vi.fn((input) => {
87				trace?.push("journal");
88				const existing = rows.find((row) => row.vertexDigest === input.vertexDigest);
89				if (existing !== undefined) {
90					return Promise.resolve(
91						Object.freeze({
92							idempotent: true,
93							journalSequence: existing.journalSequence,
94							ok: true as const,
95							scope,
96							sourceKind: existing.sourceKind,
97							vertexDigest: existing.vertexDigest,
98						})
99					);
100				}
101				const row = Object.freeze({ ...input, journalSequence: rows.length }) as LiveJournalAcceptedRow;
102				rows.push(row);
103				return Promise.resolve(
104					Object.freeze({
105						idempotent: false,
106						journalSequence: row.journalSequence,
107						ok: true as const,
108						scope,
109						sourceKind: input.sourceKind,
110						vertexDigest: input.vertexDigest,
111					})
112				);
113			}),
114			close: vi.fn(() => Promise.resolve()),
115			installEpochAnchor: vi.fn(() =>
116				Promise.reject(new Error("unexpected installEpochAnchor in live snapshot fixture"))
117			),
118			installGenesis: vi.fn(() => {
119				const idempotent = genesisInstalled;
120				genesisInstalled = true;
121				return Promise.resolve(
122					Object.freeze({
123						idempotent,
124						ok: true as const,
125						parametersDigest: fixture.descriptor.parametersDigest,
126						scope,
127					})
128				);
129			}),
130			readiness: vi.fn(() =>
131				Promise.resolve(
132					Object.freeze({ ok: true as const, ready: true as const, rowCount: rows.length, scope, snapshot: snapshot() })
133				)
134			),
135			readPage: vi.fn((input) => {
136				const index = input.afterSequence === null || input.afterSequence === undefined ? 0 : input.afterSequence + 1;
137				const row = rows[index];
138				return Promise.resolve(
139					Object.freeze({
140						nextSequence: row !== undefined && index + 1 < rows.length ? index : null,
141						ok: true as const,
142						rows: Object.freeze(row === undefined ? [] : [row]),
143						scope,
144						snapshot: input.snapshot,
145					})
146				);
147			}),
148		});
149	}
150	
151	function lowerHex(bytes: Uint8Array): string {
152		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
153	}
154	
155	async function recoveryCarrier(
156		fixture: GenuinePreparedV3Fixture,
157		recoveryOperation?: Readonly<Record<string, unknown>>
158	): Promise<Readonly<{ canonicalPreimageBytes: Uint8Array; digest: Uint8Array; signature: Uint8Array }>> {
159		if (recoveryOperation === undefined) return fixture.createRecoveryVertex(0, [fixture.anchorDigest]);
160		const canonicalPreimageBytes = encodeCanonical({
161			anchor: fixture.anchorDigest,
162			author: fixture.author,
163			authorSequence: 0,
164			dependencies: [fixture.anchorDigest],
165			epoch: 0,
166			kind: "drp-vertex",
167			logicalTime: 1,
168			objectId: fixture.objectId,
169			operation: recoveryOperation,
170			protocolMajor: 3,
171		});
172		const digest = hashDomain("ts-drp/vertex/v3", canonicalPreimageBytes);
173		return Object.freeze({
174			canonicalPreimageBytes,
175			digest,
176			signature: await fixture.signRegisteredVertexDigest(digest),
177		});
178	}
179	
180	async function recoveryStore(
181		fixture: GenuinePreparedV3Fixture,
182		recoveryOperation?: Readonly<Record<string, unknown>>,
183		trace?: string[]
184	): Promise<Readonly<{ readonly store: DurableIssuanceStore; readonly vertexDigest: string }>> {
185		const scope: DurableIssueScope = Object.freeze({ author: fixture.author, objectId: fixture.objectId });
186		const carrier = await recoveryCarrier(fixture, recoveryOperation);
187		const envelope = Object.freeze({
188			canonicalPreimageBytes: new Uint8Array(carrier.canonicalPreimageBytes),
189			digest: new Uint8Array(carrier.digest),
190			signature: new Uint8Array(carrier.signature),
191		});
192		const commit: DurableIssueCommit = Object.freeze({
193			authorSequence: 0,
194			envelope,
195			issuedRecord: Object.freeze({ authorSequence: 0, envelope, scope }),
196			outboxEntry: Object.freeze({ authorSequence: 0, envelope, scope }),
197		});
198		const commits = new Map<number, DurableIssueCommit>([[0, commit]]);
199		const outbox = new Map<number, DurableIssuanceOutboxRecord>([
200			[0, Object.freeze({ commit, publishState: "published" })],
201		]);
202		let nextAuthorSequence = 1;
203		let settlementPlan: SettlementPlan | null = null;
204		const store = Object.freeze({
205			close: vi.fn(() => Promise.resolve()),
206			compareAndMarkOutboxPublished: vi.fn((input) => {
207				const selected = outbox.get(input.authorSequence);
208				if (selected !== undefined) {
209					outbox.set(input.authorSequence, Object.freeze({ commit: selected.commit, publishState: "published" }));
210				}
211				return Promise.resolve();
212			}),
213			readIssued: vi.fn((selectedScope, sequence) =>
214				Promise.resolve(
215					selectedScope.author === scope.author && selectedScope.objectId === scope.objectId
216						? (commits.get(sequence) ?? null)
217						: null
218				)
219			),
220			readLineage: vi.fn(() => Promise.resolve({ exhausted: false, next: nextAuthorSequence })),
221			readOutboxPage: vi.fn((input = {}) => {
222				const after = input.afterKey?.[2] ?? -1;
223				return Promise.resolve(
224					Object.freeze(
225						[...outbox.entries()]
226							.filter(([sequence]) => sequence > after)
227							.sort(([left], [right]) => left - right)
228							.slice(0, input.limit ?? outbox.size)
229							.map(([, value]) => value)
230					)
231				);
232			}),
233			readSettlementPlan: vi.fn(() => Promise.resolve(settlementPlan)),
234			transactIssue: vi.fn(async (selectedScope, buildAndSign) => {
235				trace?.push("issuance");
236				if (selectedScope.author !== scope.author || selectedScope.objectId !== scope.objectId) {
237					throw new TypeError("issuance scope mismatch");
238				}
239				const issued = await buildAndSign(nextAuthorSequence);
240				if (issued.planEffect?.kind === "fence") {
241					if (settlementPlan === null || settlementPlan.fenceSequence !== null) {
242						throw new TypeError("settlement fence plan is unavailable");
243					}
244					settlementPlan = Object.freeze({
245						...settlementPlan,
246						fenceSequence: nextAuthorSequence,
247						revision: settlementPlan.revision + 1,
248					});
249				} else if (issued.planEffect?.kind === "replacement") {
250					const entry = settlementPlan?.entries.find(
251						(candidate) => candidate.sourceSequence === issued.planEffect?.sourceSequence
252					);
253					if (settlementPlan === null || entry === undefined || entry.replacementSequence !== null) {
254						throw new TypeError("settlement replacement plan is unavailable");
255					}
256					settlementPlan = Object.freeze({
257						...settlementPlan,
258						entries: Object.freeze(
259							settlementPlan.entries.map((candidate) =>
260								candidate === entry ? Object.freeze({ ...candidate, replacementSequence: nextAuthorSequence }) : candidate
261							)
262						),
263						revision: settlementPlan.revision + 1,
264					});
265				}
266				commits.set(nextAuthorSequence, issued);
267				outbox.set(nextAuthorSequence, Object.freeze({ commit: issued, publishState: "pending" }));
268				nextAuthorSequence += 1;
269				return issued;
270			}),
271			transactWriteSettlementPlan: vi.fn((input: Parameters<DurableIssuanceStore["transactWriteSettlementPlan"]>[0]) => {
272				if (input.scope.author !== scope.author || input.scope.objectId !== scope.objectId) {
273					return Promise.reject(new TypeError("settlement plan scope mismatch"));
274				}
275				if ((settlementPlan?.revision ?? null) !== input.expectedRevision) {
276					return Promise.reject(new TypeError("settlement plan revision mismatch"));
277				}
278				const nextPlan: SettlementPlan = Object.freeze({
279					...input.plan,
280					entries: Object.freeze(input.plan.entries.map((entry) => Object.freeze({ ...entry }))),
281					revision: (settlementPlan?.revision ?? -1) + 1,
282					scope,
283				});
284				settlementPlan = nextPlan;
285				return Promise.resolve(nextPlan);
286			}),
287		});
288		return Object.freeze({ store, vertexDigest: lowerHex(carrier.digest) });
289	}
290	
291	/**
292	 * Builds detached recovery bindings for focused closed-input and policy tests.
293	 * @param fixture - Authenticated live fixture that minted the capability.
294	 * @param capability - Prepared capability selected by the caller.
295	 * @param recoveryOperation - Optional exact vertex operation for the recovered row.
296	 * @param trace - Optional shared event trace for durable-order assertions.
297	 * @returns A closed public recovery input and its evidence owners.
298	 */
299	export async function createRecoveryInput(
300		fixture: GenuinePreparedV3Fixture,
301		capability: PreparedV3Live,
302		recoveryOperation?: Readonly<Record<string, unknown>>,
303		trace?: string[]
304	): Promise<
305		Readonly<{
306			readonly input: Parameters<typeof recoverV3LiveReplica>[0];
307			readonly issuanceStore: DurableIssuanceStore;
308			readonly journal: DurableLiveJournalStore;
309			readonly recoveryVertexDigest: string;
310		}>
311	> {
312		const recoveredStore = await recoveryStore(fixture, recoveryOperation, trace);
313		const journal = journalStore(fixture, trace);
314		const input = Object.freeze({
315			capability,
316			...(fixture.exactCanonicalLatchedAclBytes === undefined
317				? { exactCanonicalAuthorAuthorizationBytes: fixture.exactCanonicalAuthorAuthorizationBytes }
318				: { exactCanonicalLatchedAclBytes: fixture.exactCanonicalLatchedAclBytes }),
319			issuanceScope: Object.freeze({ author: fixture.author, objectId: fixture.objectId }),
320			issuanceStore: recoveredStore.store,
321			liveJournalStore: journal,
322		}) as Parameters<typeof recoverV3LiveReplica>[0];
323		return Object.freeze({
324			input,
325			issuanceStore: recoveredStore.store,
326			journal,
327			recoveryVertexDigest: recoveredStore.vertexDigest,
328		});
329	}
