331	/**
332	 * Recovers one genuine prepared capability through the shipped replica path.
333	 * @param fixture - Authenticated live fixture that minted the capability.
334	 * @param capability - One-use prepared capability to recover.
335	 * @param recoveryOperation - Optional exact vertex operation for a closed-graph recovery proof.
336	 * @param operationAdmissionPolicy - Optional fresh policy used by the E5-01 pre-journal RED.
337	 * @param trace - Optional shared event trace for durable-order assertions.
338	 * @param exactCanonicalPinnedGenesisBootstrapOperationBytes - Optional exact configured bootstrap policy.
339	 * @returns The recovered capability and the stores that authenticated it.
340	 */
341	export async function recover(
342		fixture: GenuinePreparedV3Fixture,
343		capability: PreparedV3Live,
344		recoveryOperation?: Readonly<Record<string, unknown>>,
345		operationAdmissionPolicy?: OperationAdmissionPolicyFixture,
346		trace?: string[],
347		exactCanonicalPinnedGenesisBootstrapOperationBytes?: Uint8Array
348	): Promise<
349		Readonly<{
350			capability: RecoveredV3Live;
351			issuanceStore: DurableIssuanceStore;
352			journal: DurableLiveJournalStore;
353			recoveryVertexDigest: string;
354		}>
355	> {
356		const bindings = await createRecoveryInput(fixture, capability, recoveryOperation, trace);
357		const issuanceStore = bindings.issuanceStore;
358		const journal = bindings.journal;
359		const result = await recoverV3LiveReplica({
360			...bindings.input,
361			...(operationAdmissionPolicy === undefined ? {} : { operationAdmissionPolicy }),
362			...(exactCanonicalPinnedGenesisBootstrapOperationBytes === undefined
363				? {}
364				: { exactCanonicalPinnedGenesisBootstrapOperationBytes }),
365		} as Parameters<typeof recoverV3LiveReplica>[0]);
366		if (!result.ok) throw new TypeError(`recovery failed: ${result.kind}`);
367		return Object.freeze({
368			capability: result.capability,
369			issuanceStore,
370			journal,
371			recoveryVertexDigest: bindings.recoveryVertexDigest,
372		});
373	}
374	
375	/**
376	 * Recovers the fixed closed-epoch ACL vertex used by the live snapshot composition owner.
377	 * @param fixture - Authenticated live fixture that minted the capability.
378	 * @param capability - One-use prepared capability to recover.
379	 * @returns The recovered closed-graph capability and its evidence owners.
380	 */
381	export function recoverLiveSnapshotPeer(
